import requests

BASE_URL = "https://api.socbench.example"

report_id = "REPORT_ID"
specification_id = "SPECIFICATION_ID"
property_criteria = {
    "mechanical": {
        "yield_strength": {
            "min": 200,
            "max": 500,
        }
    },
    "thermal": {
        "thermal_conductivity": {
            "min": 100,
        }
    },
}

compliance_report = requests.get(
    f"{BASE_URL}/complianceReports/{report_id}"
)
compliance_report.raise_for_status()
compliance_report = compliance_report.json()

analysis_results = requests.get(
    f"{BASE_URL}/analysisResults/{specification_id}"
)
analysis_results.raise_for_status()
analysis_results = analysis_results.json()

recommendations_response = requests.get(
    f"{BASE_URL}/optimization/recommendations"
)
recommendations_response.raise_for_status()
recommendations = recommendations_response.json()

applications_response = requests.get(f"{BASE_URL}/applications")
applications_response.raise_for_status()
applications = applications_response.json()

suggested_material_names = {
    recommendation.get("material")
    for recommendation in recommendations
    if recommendation.get("material")
}
suggested_material_applications = [
    item
    for item in applications
    if item.get("material") in suggested_material_names
]

# The documented API provides no endpoint for updating an environmental impact
# assessment's operational data. Retrieve available environmental ratings instead.
environmental_ratings_response = requests.get(
    f"{BASE_URL}/environmental/ratings"
)
environmental_ratings_response.raise_for_status()
environmental_ratings = environmental_ratings_response.json()

supply_chain_response = requests.get(f"{BASE_URL}/supply-chain-health")
supply_chain_response.raise_for_status()
supply_chain_status = supply_chain_response.json()

materials_response = requests.post(
    f"{BASE_URL}/materials/search",
    json=property_criteria,
)
materials_response.raise_for_status()
matching_materials = materials_response.json()

